// Cache entry metadata
struct CacheEntryHeader {
    uint32_t magic;
    uint32_t content_length;
    uint32_t header_length;
    uint32_t flags;
    char etag[64];
};

class MemoryPool {
private:
    std::vector<uint8_t> pool_;
    size_t offset_;
    std::mutex mtx_;

public:
    MemoryPool(size_t initial_size) : pool_(initial_size, 0), offset_(0) {}

    // Allocate 'size' bytes and return the byte offset within the pool.
    // Returning an offset (rather than a raw pointer) keeps references valid
    // even if the underlying buffer is reallocated on resize.
    size_t allocate(size_t size) {
        std::lock_guard<std::mutex> lock(mtx_);
        if (offset_ + size > pool_.size()) {
            pool_.resize(pool_.size() * 2 + size);
        }
        size_t alloc_offset = offset_;
        offset_ += size;
        return alloc_offset;
    }

    // Access data at a given offset. Must be called while holding no allocation
    // that could resize the pool in between use.
    uint8_t* data_at(size_t off) {
        std::lock_guard<std::mutex> lock(mtx_);
        return pool_.data() + off;
    }

    void write(size_t off, const void* src, size_t len) {
        std::lock_guard<std::mutex> lock(mtx_);
        std::memcpy(pool_.data() + off, src, len);
    }

    void reset() {
        std::lock_guard<std::mutex> lock(mtx_);
        offset_ = 0;
    }

    size_t used() {
        std::lock_guard<std::mutex> lock(mtx_);
        return offset_;
    }
    size_t capacity() {
        std::lock_guard<std::mutex> lock(mtx_);
        return pool_.size();
    }
};

class HttpResponseCache {
private:
    MemoryPool pool_;
    std::unordered_map<std::string, size_t> index_;
    std::mutex index_mtx_;
    static constexpr uint32_t CACHE_MAGIC = 0xCAFEBABE;
    static constexpr size_t MAX_POOL_SIZE = 512 * 1024 * 1024; // 512MB
    static constexpr size_t MAX_ENTRY_SIZE = 256 * 1024 * 1024; // 256MB per entry

    // Compute total allocation size for a cache entry
    // Uses size_t to prevent overflow
    size_t compute_entry_size(size_t header_len, size_t content_len) {
        size_t metadata_size = sizeof(CacheEntryHeader);
        // Check for overflow before addition
        if (header_len > MAX_ENTRY_SIZE || content_len > MAX_ENTRY_SIZE) {
            return 0;
        }
        size_t total = metadata_size + header_len + content_len;
        // Verify no wraparound occurred
        if (total < metadata_size || total < header_len || total < content_len) {
            return 0;
        }
        return total;
    }

public:
    HttpResponseCache() : pool_(64 * 1024 * 1024) {} // 64MB initial

    bool store(const std::string& url,
              const std::string& response_headers,
              const std::vector<uint8_t>& content,
              const std::string& etag) {

        size_t header_len = response_headers.size();
        size_t content_len = content.size();

        // Check pool capacity
        if (pool_.used() > MAX_POOL_SIZE) {
            return false;
        }

        // Compute total entry size with overflow protection
        size_t entry_size = compute_entry_size(header_len, content_len);
        if (entry_size == 0) {
            return false;
        }

        // Additional bound check
        if (entry_size > MAX_ENTRY_SIZE) {
            return false;
        }

        // Allocate from pool (returns a stable offset, resize-safe)
        size_t entry_off = pool_.allocate(entry_size);

        // Build header locally, then copy into the pool. Using offsets and
        // per-write locking avoids dangling pointers across reallocations.
        CacheEntryHeader hdr;
        hdr.magic = CACHE_MAGIC;
        hdr.content_length = static_cast<uint32_t>(std::min(content_len, static_cast<size_t>(UINT32_MAX)));
        hdr.header_length = static_cast<uint32_t>(std::min(header_len, static_cast<size_t>(UINT32_MAX)));
        hdr.flags = 0;
        std::memset(hdr.etag, 0, sizeof(hdr.etag));
        std::memcpy(hdr.etag, etag.c_str(),
                    std::min(etag.size(), sizeof(hdr.etag) - 1));

        // Write header
        pool_.write(entry_off, &hdr, sizeof(CacheEntryHeader));

        // Write response headers after metadata
        size_t headers_off = entry_off + sizeof(CacheEntryHeader);
        pool_.write(headers_off, response_headers.data(), header_len);

        // Write content after headers
        size_t content_off = headers_off + header_len;
        pool_.write(content_off, content.data(), content_len);

        // Index the entry by its stable offset
        {
            std::lock_guard<std::mutex> lock(index_mtx_);
            index_[url] = entry_off;
        }

        return true;
    }

    bool retrieve(const std::string& url, std::string& out_headers,
                  std::vector<uint8_t>& out_content) {
        std::lock_guard<std::mutex> lock(index_mtx_);
        auto it = index_.find(url);
        if (it == index_.end()) return false;
        // Retrieval logic omitted for brevity
        return true;
    }
};

// Proxy server that caches upstream responses
class CachingProxy {
private:
    HttpResponseCache cache_;
    std::string upstream_host_;
    uint16_t upstream_port_;

    // Simulate fetching from upstream
    bool fetch_upstream(const std::string& path,
                       std::string& resp_headers,
                       std::vector<uint8_t>& resp_body) {
        // In production this would make an HTTP request
        // For demonstration, read from local filesystem
        std::string safe_path = "/var/cache/proxy";

        // Path validation - prevent traversal
        if (path.find("..") != std::string::npos) {
            return false;
        }
        if (path.empty() || path[0] != '/') {
            return false;
        }
        // Only allow alphanumeric, dash, dot, slash
        for (char c : path) {
            if (!std::isalnum(static_cast<unsigned char>(c)) &&
                c != '/' && c != '-' && c != '.' && c != '_') {
                return false;
            }
        }
        safe_path += path;

        std::ifstream file(safe_path, std::ios::binary);
        if (!file) return false;

        file.seekg(0, std::ios::end);
        auto size = file.tellg();
        file.seekg(0, std::ios::beg);

        // Reject files larger than max entry size
        if (size < 0 || static_cast<size_t>(size) > 256 * 1024 * 1024) {
            return false;
        }

        resp_body.resize(static_cast<size_t>(size));
        file.read(reinterpret_cast<char*>(resp_body.data()), size);

        resp_headers = "HTTP/1.1 200 OK\r\nContent-Length: " +
                      std::to_string(size) + "\r\n\r\n";
        return true;
    }

public:
    CachingProxy(const std::string& host, uint16_t port)
        : upstream_host_(host), upstream_port_(port) {}

    bool handle_request(const std::string& path) {
        std::string headers;
        std::vector<uint8_t> body;

        if (!fetch_upstream(path, headers, body)) {
            return false;
        }

        // Generate etag from content size
        std::string etag = "\"" + std::to_string(body.size()) + "\"";

        // Cache the response
        return cache_.store(path, headers, body, etag);
    }
};

int main() {
    CachingProxy proxy("backend.internal", 8080);
    // Handle incoming requests
    proxy.handle_request("/large-asset.bin");
    return 0;
}
